     3	public class ClaimOffice {
     4	
     5	    private static final int PROCESSING_FEE_IN_G = 5;
     6	
     7	    private static final int LOYALTY_YEARS = 2;
     8	
     9	    private static final int LOYALTY_DISCOUNT_PERCENT = 20;
    10	
    11	    private final Customer customer;
    12	
    13	    public ClaimOffice(Customer customer) {
    14	        this.customer = customer;
    15	    }
    16	
    17	    /**
    18	     * The policy base premium is the sum of the base premiums of the main items
    19	     * and of the components, each priced by its own MHPCO pricing policy.
    20	     */
    21	    public int basePremium(List<Item> items) {
    22	        return MainItemPricing.mainItemsBasePremium(items)
    23	                + ComponentPricing.componentsBasePremium(items);
    24	    }
    25	
    26	    /**
    27	     * Item-specific modifiers apply to the base premium of the affected item,
    28	     * not to the policy total.
    29	     */
    30	    public int premiumAfterItemModifiers(List<Item> items) {
    31	        return basePremium(items) + ItemRiskSurcharges.totalItemSurcharges(items);
    32	    }
    33	
    34	    /**
    35	     * Policy-wide modifiers apply to the policy premium; the processing fee is
    36	     * added at the very end.
    37	     */
    38	    public int quote(List<Item> items) {
    39	        int premium = premiumAfterItemModifiers(items);
    40	        return premium - loyaltyDiscount(premium) + PROCESSING_FEE_IN_G;
    41	    }
    42	
    43	    /**
    44	     * Long-standing customers -- 2 or more years of business with the MHPCO --
    45	     * receive a 20 % loyalty discount on the policy premium.
    46	     */
    47	    private int loyaltyDiscount(int premium) {
    48	        if (customer.yearsWithMHPCO() < LOYALTY_YEARS) {
    49	            return 0;
    50	        }
    51	        return premium * LOYALTY_DISCOUNT_PERCENT / 100;
    52	    }
    53	}
