     1	import java.util.List;
     2	import java.util.function.Predicate;
     3	
     4	/**
     5	 * The MHPCO's item-specific risk surcharges. A surcharge is charged only for
     6	 * the items that carry the risk, and is measured against that item's own base
     7	 * premium -- never against the policy total.
     8	 */
     9	public final class ItemRiskSurcharges {
    10	
    11	    private static final int CURSE_SURCHARGE_PERCENT = 50;
    12	
    13	    private static final int HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
    14	
    15	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
    16	
    17	    private ItemRiskSurcharges() {
    18	    }
    19	
    20	    /**
    21	     * Every item-specific risk surcharge the MHPCO charges, summed. This is the
    22	     * one place that says which risks are item-specific: a new item risk is
    23	     * added here and nowhere else.
    24	     */
    25	    public static int totalItemSurcharges(List<Item> items) {
    26	        return curseSurcharge(items) + highEnchantmentSurcharge(items);
    27	    }
    28	
    29	    /**
    30	     * Cursed items add a 50 % risk surcharge on their own base premium.
    31	     */
    32	    private static int curseSurcharge(List<Item> items) {
    33	        return surchargeOnItemsAtRisk(items, Item::cursed, CURSE_SURCHARGE_PERCENT);
    34	    }
    35	
    36	    /**
    37	     * Highly enchanted items -- enchantment level 5 or more -- add a 30 % risk
    38	     * surcharge on their own base premium.
    39	     */
    40	    private static int highEnchantmentSurcharge(List<Item> items) {
    41	        return surchargeOnItemsAtRisk(
    42	                items, ItemRiskSurcharges::isHighlyEnchanted, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
    43	    }
    44	
    45	    private static boolean isHighlyEnchanted(Item item) {
    46	        return item.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
    47	    }
    48	
    49	    /**
    50	     * The MHPCO's scope rule for every item-specific surcharge, decided in one
    51	     * place: only the items carrying the risk are charged, each against its own
    52	     * base premium, and the amounts are summed into the policy premium.
    53	     */
    54	    private static int surchargeOnItemsAtRisk(
    55	            List<Item> items, Predicate<Item> carriesTheRisk, int surchargePercent) {
    56	        return items.stream()
    57	                .filter(carriesTheRisk)
    58	                .mapToInt(item -> MainItemPricing.basePremium(item) * surchargePercent / 100)
    59	                .sum();
    60	    }
    61	}
